<style>
  #logo-stage { display:flex; flex-direction:column; align-items:center; justify-content:center; padding:24px 12px; min-height:380px; background:var(--viz-panel, #0e1117); color:var(--viz-text, #e8eaed); }
  .scene { width:220px; height:220px; perspective:900px; }
  .cube { width:100%; height:100%; position:relative; transform-style:preserve-3d; transform: rotateX(-18deg) rotateY(28deg); animation:spin 9s linear infinite; }
  .cube.paused { animation-play-state:paused; }
  .face { position:absolute; inset:0; border:2px solid var(--viz-accent, #6ea8fe); background:rgba(110,168,254,0.12); backface-visibility:visible; display:flex; align-items:center; justify-content:center; font-weight:700; font-size:42px; color:var(--viz-accent, #6ea8fe); border-radius:16px; box-shadow: inset 0 0 40px rgba(110,168,254,0.15); }
  .face.front  { transform: translateZ(110px); }
  .face.back   { transform: rotateY(180deg) translateZ(110px); }
  .face.right  { transform: rotateY(90deg) translateZ(110px); }
  .face.left   { transform: rotateY(-90deg) translateZ(110px); }
  .face.top    { transform: rotateX(90deg) translateZ(110px); }
  .face.bottom { transform: rotateX(-90deg) translateZ(110px); }
  @keyframes spin { from { transform: rotateX(-18deg) rotateY(0deg); } to { transform: rotateX(-18deg) rotateY(360deg); } }
  .hint { margin-top:18px; font-size:12px; color:var(--viz-muted, #9aa0a6); }
  .face::before { content:"G"; }
</style>
<script>
  const cube = document.getElementById('cube');
  let dragging=false, lastX=0, lastY=0, rx=-18, ry=28;
  cube.style.animation = 'none';
  cube.style.transform = `rotateX(${rx}deg) rotateY(${ry}deg)`;
  const startDrag = (x,y) => { dragging=true; lastX=x; lastY=y; cube.classList.add('paused'); };
  const moveDrag = (x,y) => { if(!dragging) return; ry += (x-lastX)*0.5; rx -= (y-lastY)*0.5; lastX=x; lastY=y; cube.style.transform = `rotateX(${rx}deg) rotateY(${ry}deg)`; };
  const endDrag = () => { dragging=false; };
  cube.addEventListener('mousedown', e=>startDrag(e.clientX,e.clientY));
  window.addEventListener('mousemove', e=>moveDrag(e.clientX,e.clientY));
  window.addEventListener('mouseup', endDrag);
  cube.addEventListener('touchstart', e=>{const t=e.touches[0];startDrag(t.clientX,t.clientY);},{passive:true});
  window.addEventListener('touchmove', e=>{const t=e.touches[0];moveDrag(t.clientX,t.clientY);},{passive:true});
  window.addEventListener('touchend', endDrag);
  let paused=false;
  window.addEventListener('keydown', e=>{ if(e.code==='Space'){ e.preventDefault(); paused=!paused; if(paused){ cube.style.transform = `rotateX(${rx}deg) rotateY(${ry}deg)`; cube.classList.add('paused'); } else { cube.classList.remove('paused'); cube.style.animation=''; } } });
</script>

